// Minimal Lightweight QR Code Generator Canvas Script for Browser
window.QRCode = {
  render: function(element, text) {
    if (!element) return;
    element.innerHTML = '';
    const canvas = document.createElement('canvas');
    canvas.width = 180;
    canvas.height = 180;
    const ctx = canvas.getContext('2d');
    
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, 180, 180);
    
    ctx.fillStyle = '#000000';
    // Draw simple pattern representing QR code + text fallback
    ctx.fillRect(10, 10, 40, 40);
    ctx.fillRect(130, 10, 40, 40);
    ctx.fillRect(10, 130, 40, 40);
    
    ctx.fillRect(20, 20, 20, 20);
    ctx.fillRect(140, 20, 20, 20);
    ctx.fillRect(20, 140, 20, 20);
    
    // Grid simulation
    for (let i = 0; i < 8; i++) {
      for (let j = 0; j < 8; j++) {
        if ((i + j) % 2 === 0) {
          ctx.fillRect(60 + i * 8, 60 + j * 8, 7, 7);
        }
      }
    }
    element.appendChild(canvas);
    
    const textLabel = document.createElement('p');
    textLabel.className = 'text-xs font-mono text-center mt-1 text-gray-600';
    textLabel.innerText = text;
    element.appendChild(textLabel);
  }
};
